/*
 * Fallback typeface for the quotation PDF.
 *
 * Gotham is licensed, so it cannot live in a public repository. This is Montserrat
 * (SIL Open Font License 1.1) — a geometric sans cut close enough to Gotham that a
 * quote reads correctly before your own font files are dropped into assets/fonts/.
 * Instanced to two weights and subsetted to Latin plus the punctuation and currency
 * a quotation prints, which is why it is ~50 KB a weight rather than ~200 KB.
 *
 * Generated; do not hand-edit. See assets/fonts/README.md.
 */

export const FALLBACK_NORMAL = '';
export const FALLBACK_BOLD = '';

export const FALLBACK_FAMILY = 'LaFugaSans';
export const FALLBACK_CREDIT = 'Montserrat (OFL 1.1)';
